// World Health & Disparities Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–4.
import {q, mix} from './q.js';
const BARR='Barr, Health Disparities in the United States', WHO='WHO, Health Equity', NIMHD='National Institute on Minority Health and Health Disparities', KFF='KFF', OWID='Our World in Data';
const WH='What is Health', HD='Health Disparities & Diversity', TR='Disparities in Treatment & Medical Decisions', RED='Reducing Health Disparities';

export default {
 id:'world-health-disparities-5',
 event:'World Health & Disparities',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Barr’s Health Disparities in the United States, WHO health equity materials, NIMHD, KFF and Our World in Data',
 plan:[{area:WH,weight:20},{area:HD,weight:40},{area:TR,weight:20},{area:RED,weight:20}],
 questions:mix([
  q(WH,'Which large international research effort estimates deaths and disability from hundreds of diseases and risk factors in every country?','The Global Burden of Disease study',['The Human Development Report','The World Values Survey','The Framingham Heart Study'],'A','The Global Burden of Disease study, led by IHME, uses measures such as DALYs to compare health losses.',OWID),
  q(WH,'Which measure counts deaths before age 5 per 1,000 live births and is tracked under SDG target 3.2?','Under-5 mortality rate',['Infant mortality rate','Neonatal mortality rate','Perinatal mortality rate'],'B','Under-5 mortality is a key measure of child health and of a country’s overall development.',WHO),
  q(WH,'Neonatal mortality counts deaths of infants during which period?','The first 28 days of life',['The first 7 days of life','The first full year of life','The first five years of life'],'C','Nearly half of deaths in children under 5 occur in the neonatal period.',WHO),
  q(WH,'As countries develop, populations shift from high birth and death rates to low birth and death rates. What is this called?','The demographic transition',['The epidemiologic transition','The nutrition transition','The urban transition'],'D','Falling death rates usually come first, so populations grow rapidly before birth rates fall.',OWID),
  q(WH,'The WHO describes six building blocks of a health system. Which is one of them?','Health workforce',['Military defense','Tourism','Agriculture'],'A','The others are service delivery, information, medical products, financing and leadership or governance.',WHO),
  q(WH,'When a household spends more than a set share, such as 10%, of its budget on health care out of pocket, this spending is called:','Catastrophic health spending',['Preventive health spending','Discretionary health spending','Pooled health spending'],'B','Catastrophic spending can push families into poverty and is tracked under the SDGs.',WHO),
  q(WH,'How does absolute poverty differ from relative poverty?','Absolute poverty means lacking basic needs; relative poverty compares to others',['Absolute poverty is measured only in high-income countries','Relative poverty means having no income or assets at all','They are two names for the same World Bank measure'],'C','Both kinds of poverty are linked to poorer health, through different pathways.',OWID),
  q(WH,'Which public–private partnership helps lower-income countries buy and deliver vaccines?','Gavi, the Vaccine Alliance',['The World Trade Organization','The International Monetary Fund','The Red Cross Blood Service'],'D','Gavi has helped vaccinate hundreds of millions of children in low-income countries.',WHO),
  q(WH,'Which model shows layers of influence on health, from age and genes at the center to broad social, economic and environmental conditions?','The Dahlgren–Whitehead rainbow model',['The Health Belief Model','The Stages of Change model','The Swiss cheese model'],'A','The model shows how individual factors sit inside wider living, working and social conditions.',WHO),
  q(WH,'A graph shows a country’s population by age and sex as stacked bars. What is it called?','A population pyramid',['A Lorenz curve','A Gantt chart','A forest plot'],'B','A wide base suggests high birth rates; a narrow base suggests an aging population.',OWID),
  q(HD,'A neighborhood has many fast-food outlets and convenience stores but few healthy food options. What is it called?','A food swamp',['A food bank','A food hub','A food cooperative'],'C','Food swamps may predict obesity even better than a simple lack of grocery stores.',BARR),
  q(HD,'A county with no hospital offering obstetric care and no obstetric providers is called a:','Maternity care desert',['Medical home zone','Health enterprise zone','Primary care cluster'],'D','Long travel to give birth is linked with higher risks for mothers and babies.',NIMHD),
  q(HD,'Compared with white adults with diabetes, Black adults with diabetes are more likely to experience which outcome?','Lower-limb amputation',['Lower blood pressure','Fewer kidney problems','Fewer eye problems'],'A','Later diagnosis of circulation problems and less access to specialist care contribute to this gap.',NIMHD),
  q(HD,'Which U.S. group has the highest death rate from chronic liver disease and cirrhosis?','American Indian and Alaska Native people',['Asian American and Pacific Islander people','Non-Hispanic white people in rural areas','Hispanic people born in the United States'],'B','Factors include alcohol use, hepatitis C and limited access to care in some communities.',NIMHD),
  q(HD,'Which group of U.S. women has the highest rate of new cervical cancer cases?','Hispanic women',['Asian American women','Non-Hispanic white women','Women over 85'],'C','Lower screening and HPV vaccination rates contribute to this disparity.',NIMHD),
  q(HD,'How does breast cancer among Black women compare with that among white women in the U.S.?','Similar rates of diagnosis but higher death rates',['Much lower rates of both diagnosis and death','Higher rates of diagnosis but lower death rates','No difference in either diagnosis or death'],'D','Later diagnosis, more aggressive subtypes and unequal treatment all play a role.',NIMHD),
  q(HD,'Most tuberculosis cases in the United States occur among which group?','People born outside the United States',['Children under age 5 in day care','Health care workers in hospitals','Adults over age 90 in nursing homes'],'A','Many cases are latent infections acquired abroad that become active years later.',NIMHD),
  q(HD,'Which U.S. group has the highest rate of high blood pressure?','Black adults',['Asian American adults','Hispanic adults','White adults'],'B','High blood pressure also tends to develop earlier and be more severe in Black adults.',NIMHD),
  q(HD,'Which U.S. group is among the least likely to use mental health services when needed?','Asian Americans',['White adults with insurance','Adults over 65','College graduates'],'C','Stigma, language barriers and a lack of culturally matched providers contribute.',NIMHD),
  q(HD,'Under the Americans with Disabilities Act, what must health care providers usually supply for a Deaf patient who uses ASL?','A qualified sign language interpreter',['A family member to interpret','A printed brochure only','A note asking them to reschedule'],'D','Effective communication is required so the patient can understand and consent to care.',BARR),
  q(HD,'People lose Medicaid coverage and re-enroll a few months later, often because of paperwork. What is this called?','Churn',['Crowd-out','Cost-sharing','Spend-down'],'A','Gaps in coverage interrupt care and medicines, especially for chronic conditions.',KFF),
  q(HD,'A neighborhood with sidewalks, parks and nearby shops that encourage walking is described as having high:','Walkability',['Density bonus','Food insecurity','Segregation index'],'B','Walkable neighborhoods are linked with more physical activity and lower obesity rates.',BARR),
  q(HD,'Why is social isolation among older adults considered a health risk?','It is linked to higher risks of dementia, heart disease and early death',['It lowers the risk of infection enough to improve health','It only affects mood, not physical health','It mainly affects adults under age 30'],'C','The risk from isolation is often compared with that of smoking or obesity.',BARR),
  q(HD,'Why do researchers study the racial wealth gap, not only the income gap?','Wealth reflects assets built over generations that cushion health shocks',['Wealth and income always differ by the same fixed amount in every group','Wealth data are easier to collect accurately than income data','Income has no measurable link to health outcomes in research'],'D','Families with equal incomes can have very different savings, homes and safety nets.',BARR),
  q(HD,'A family that spends more than 30% of its income on housing is described as:','Housing cost-burdened',['Housing secure','Doubled up with family','Overhoused for their size'],'A','High housing costs leave less money for food, medicine and health care.',BARR),
  q(HD,'Globally, why is education for girls strongly linked to child health?','Educated mothers tend to have healthier children with lower death rates',['Schools in most countries provide all childhood vaccines and checkups','Girls’ education mainly raises the cost of local health care','Educated mothers tend to have larger families with more children'],'B','Education is linked to later marriage, better nutrition knowledge and more use of health services.',WHO),
  q(HD,'Which global strategy focuses on safe drinking water, toilets and handwashing?','WASH',['DOTS','IMCI','PEPFAR'],'C','Poor water, sanitation and hygiene are major causes of diarrheal disease worldwide.',WHO),
  q(HD,'Doctors and nurses trained in low-income countries move to wealthier countries for work. What is this called?','Brain drain',['Task shifting','Medical tourism','Reverse migration'],'D','Health worker migration worsens shortages in countries that already have too few clinicians.',WHO),
  q(HD,'Cholera outbreaks are most closely linked to which condition?','Lack of safe water and sanitation',['High rates of obesity','Cold winter weather','Lack of physical activity'],'A','Cholera spreads through water or food contaminated with feces.',WHO),
  q(HD,'In many low-income homes, cooking indoors over wood, charcoal or dung fires causes which health risk?','Household air pollution',['Lead poisoning from paint','Excess noise exposure','Radiation exposure'],'B','Household air pollution causes pneumonia in children and lung and heart disease in adults.',WHO),
  q(TR,'People with serious mental illness are less likely to receive which kind of care for physical conditions?','Standard heart disease treatment',['Any form of emergency care','Mental health medicines','Psychiatric hospitalization'],'C','Physical symptoms may be overlooked, contributing to shorter life expectancy.',BARR),
  q(TR,'On average, Black and Hispanic children in the U.S. receive which diagnosis later than white children?','Autism spectrum disorder',['Ear infections','Seasonal allergies','Broken bones'],'D','Later diagnosis delays early intervention services that can improve outcomes.',NIMHD),
  q(TR,'Why is using a patient’s child as an interpreter discouraged?','Errors are more likely and it may expose the child to sensitive information',['Children always translate more accurately than adults','It is faster than using a professional','Federal law requires family interpreters'],'A','Trained medical interpreters reduce errors and protect privacy.',BARR),
  q(TR,'Which computer-based test measures how quickly people link groups with positive or negative words to reveal unconscious associations?','Implicit Association Test',['Myers–Briggs Type Indicator','Mini-Mental State Exam','Beck Depression Inventory'],'B','The test is used for awareness and research, not to diagnose individual bias.',BARR),
  q(TR,'A patient avoids care because of past harm to their community by medical institutions. What is this called?','Medical mistrust',['Health literacy','Medical tourism','Defensive medicine'],'C','Building trust requires honesty, community partnership and respectful care.',BARR),
  q(TR,'Under Medicare’s readmission penalty program, which hospitals were more likely to be penalized at first?','Hospitals serving many low-income patients',['Small hospitals in wealthy suburbs','Hospitals with the most specialists','Hospitals in large teaching systems only'],'D','Social factors affect readmissions, so the program later began comparing similar hospitals.',KFF),
  q(TR,'In Black patients, melanoma is more often found at a later stage. Where does it often appear?','On the palms, soles or under the nails',['Only on the face and other sun-exposed areas','On the scalp in nearly all cases','Only inside the mouth and on the gums'],'A','This type, acral melanoma, appears in areas often missed in skin exams, so clinicians must check them.',NIMHD),
  q(TR,'Which principle of the Belmont Report requires that the burdens and benefits of research be shared fairly?','Justice',['Respect for persons','Beneficence','Autonomy'],'B','Justice means no group should carry the risks of research while others reap the benefits.',BARR),
  q(TR,'Which approach asks clinicians to keep learning about patients’ cultures and to examine their own assumptions throughout their careers?','Cultural humility',['Cultural competence checklist','Color-blind care','Cultural tourism'],'C','Cultural humility treats the patient as the expert on their own life and culture.',BARR),
  q(TR,'Compared with white patients, Black patients near the end of life are less likely to use which service?','Hospice care',['Emergency care','Intensive care','Ventilator support'],'D','Mistrust, lack of information and different preferences all contribute to this gap.',KFF),
  q(RED,'Which type of Medicaid waiver lets states test new approaches, such as paying for housing supports or food?','Section 1115 waiver',['Section 8 voucher','Title X grant','Section 504 plan'],'A','States use these waivers to address social needs that affect health.',KFF),
  q(RED,'In which prenatal care model do groups of pregnant patients meet together with a clinician for checkups and education?','Group prenatal care',['Solo prenatal care','Emergency prenatal care','Retail prenatal care'],'B','Programs such as CenteringPregnancy have been linked to fewer preterm births in some groups.',NIMHD),
  q(RED,'A study partnered pharmacists with Black-owned barbershops to manage customers’ blood pressure. What did it show?','Large drops in blood pressure',['No change in blood pressure','Higher rates of hospitalization','Fewer customers seeking care'],'C','Trusted community settings can reach people who rarely visit clinics.',NIMHD),
  q(RED,'Paramedics visit patients at home to check on chronic conditions and prevent emergencies. What is this called?','Community paramedicine',['Air medical transport','Emergency triage','Tele-intensive care'],'D','Community paramedicine is especially useful in rural areas with few clinics.',NIMHD),
  q(RED,'Which school policy gives every student free breakfast and lunch regardless of family income?','Universal free school meals',['Reduced-price lunch only','Vending machine bans','Pay-as-you-go lunch'],'A','Universal programs remove stigma and paperwork that keep eligible children from eating.',KFF),
  q(RED,'Which policy gives new parents paid time off to care for an infant?','Paid family leave',['Unpaid sick leave','Flexible spending accounts','Workers’ compensation'],'B','Paid leave is linked with higher breastfeeding rates and better infant health.',KFF),
  q(RED,'Hospitals and universities use their hiring and buying power to improve their local communities. What are they called?','Anchor institutions',['Safety-net clinics','Retail clinics','Specialty centers'],'C','Hiring locally and buying from local businesses can address economic roots of poor health.',BARR),
  q(RED,'Clinicians “prescribe” fruits and vegetables that patients can get free or at a discount. What are these programs called?','Produce prescription programs',['Meal replacement plans','Supplement programs','Calorie restriction orders'],'D','These programs aim to improve diet and blood sugar in patients facing food insecurity.',NIMHD),
  q(RED,'Which CMS model tested screening patients for social needs and linking them to community services?','Accountable Health Communities',['Medicare Advantage Value Plan','Hospital Readmissions Program','Part D Senior Savings Model'],'A','The model screened millions of beneficiaries for needs such as housing, food and transportation.',KFF),
  q(RED,'Which federal office, created in 1986 within HHS, works to improve the health of racial and ethnic minority groups?','Office of Minority Health',['Office of the Inspector General','Office of Civil Service','Office of Management and Budget'],'B','It was created after the 1985 Heckler Report documented large health gaps.',NIMHD)
 ],9541)
};
